from __future__ import annotations
from itertools import product
from typing import Dict, FrozenSet, Iterable, List, Set, Tuple

Vertex = int
VertexSet = FrozenSet[Vertex]


class UndirectedGraph:
    """Finite undirected graph: a symmetric adjacency relation on range(n)."""

    def __init__(self, n: int, edges: Iterable[Tuple[Vertex, Vertex]]) -> None:
        self.n = n
        self.adj: Dict[Vertex, Set[Vertex]] = {v: set() for v in range(n)}
        for x, y in edges:
            self.adj[x].add(y)
            self.adj[y].add(x)

    def conn_avoid(self, u: Vertex, v: Vertex, z: VertexSet) -> bool:
        """Z-avoiding reachability via BFS on the Z-deleted graph."""
        if u in z or v in z:
            return u == v and u not in z
        if u == v:
            return True
        seen, frontier = {u}, [u]
        while frontier:
            x = frontier.pop()
            for y in self.adj[x]:
                if y not in z and y not in seen:
                    if y == v:
                        return True
                    seen.add(y)
                    frontier.append(y)
        return False

    def separated(self, a: VertexSet, b: VertexSet, z: VertexSet) -> bool:
        return all(not self.conn_avoid(p, q, z) for p in a for q in b)


def disjoint_triples(n: int):
    for labels in product(range(5), repeat=n):
        a = frozenset(v for v in range(n) if labels[v] == 0)
        b = frozenset(v for v in range(n) if labels[v] == 1)
        w = frozenset(v for v in range(n) if labels[v] == 2)
        z = frozenset(v for v in range(n) if labels[v] == 3)
        yield a, b, w, z


def check_all_axioms(g: UndirectedGraph) -> Dict[str, int]:
    counts = {k: 0 for k in
              ("symmetry", "decomposition", "weak_union",
               "contraction", "composition")}
    sep = g.separated
    for a, b, w, z in disjoint_triples(g.n):
        bw, zw, zb = b | w, z | w, z | b
        if sep(a, b, z):
            assert sep(b, a, z); counts["symmetry"] += 1
        if sep(a, bw, z):
            assert sep(a, b, z); counts["decomposition"] += 1
            assert sep(a, b, zw); counts["weak_union"] += 1
        if sep(a, b, z) and sep(a, w, zb):
            assert sep(a, bw, z); counts["contraction"] += 1
        if sep(a, b, z) and sep(a, w, z):
            assert sep(a, bw, z); counts["composition"] += 1
    return counts


if __name__ == "__main__":
    g = UndirectedGraph(5, [(0,1),(1,2),(2,3),(3,4),(4,0),(0,2)])
    for name, c in check_all_axioms(g).items():
        print(f"{name:<14}: PASSED ({c} instances)")

from __future__ import annotations
from typing import Dict, Tuple


def prob_independent(joint: Dict[Tuple[int, ...], float],
                     xs: Tuple[int, ...], ys: Tuple[int, ...]) -> bool:
    """Marginal independence of variable index-sets xs, ys under `joint`."""
    def marg(idxs):
        out: Dict[Tuple[int, ...], float] = {}
        for assign, p in joint.items():
            key = tuple(assign[i] for i in idxs)
            out[key] = out.get(key, 0.0) + p
        return out
    pxy, px, py = marg(xs + ys), marg(xs), marg(ys)
    for assign, _ in joint.items():
        kx = tuple(assign[i] for i in xs)
        ky = tuple(assign[i] for i in ys)
        if abs(pxy.get(kx + ky, 0.0) - px[kx] * py[ky]) > 1e-12:
            return False
    return True


def parity_demo() -> None:
    """A = B XOR W with B, W independent fair bits; assignment order (A,B,W)."""
    joint = {(b ^ w, b, w): 0.25 for b in (0, 1) for w in (0, 1)}
    print("A independent of B     :", prob_independent(joint, (0,), (1,)))
    print("A independent of W     :", prob_independent(joint, (0,), (2,)))
    print("A independent of (B,W) :", prob_independent(joint, (0,), (1, 2)))
    print("=> composition FAILS for probabilistic independence.")


if __name__ == "__main__":
    parity_demo()

