function SEPARATED(adj, A, B, Z):
    if A ∩ B has a vertex outside Z: return False
    seen <- { a in A : a not in Z }
    frontier <- seen
    while frontier not empty:
        x <- pop(frontier)
        for y in neighbours(x):
            if y in Z or y in seen: continue
            if y in B: return False        # found an A->B walk avoiding Z
            seen <- seen ∪ {y}
            push(frontier, y)
    return True                            # no A reaches any B avoiding Z

function FIRST_HIT(walk, P):
    assert walk nonempty and not P(walk[0])
    prefix <- [walk[0]]
    for i from 1 to len(walk)-1:
        if P(walk[i]):
            return ("hit", prefix, (walk[i-1], walk[i]))
        append walk[i] to prefix
    return ("avoid", walk, none)

